/**
 * Structurally the same shape as the generated `CreateClientConfig` in
 * `generated/client.gen.ts` — deliberately *not* imported from there.
 * `src/api/generated` is excluded from `tsconfig.app.json` (it's a pure,
 * gitignored function of the OpenAPI contract, regenerated by `pnpm gen`),
 * and this file's whole job is to be imported *by* that generated output
 * (via `runtimeConfigPath`), not the other way around — a type-only import
 * back into `generated/` would pull excluded files into this project's
 * composite build and fail with TS6307. Kept intentionally loose (an object
 * of unknown extra properties in, an object out) rather than re-declaring
 * `Config`/`ClientOptions` by hand; the generated call site is the one place
 * this shape actually has to line up, and that file isn't type-checked by
 * any `tsc -b` project here.
 */
type ClientRuntimeConfig = Record<string, unknown> | undefined;

/**
 * Wired into codegen via `runtimeConfigPath` in `openapi-ts.shared.mjs`
 * (`@hey-api/client-fetch`'s documented escape hatch for exactly this case —
 * see the comment `openapi-ts` itself writes at the top of
 * `generated/client.gen.ts`). `pnpm --filter @app/web gen` regenerates
 * `src/api/generated` from `packages/contracts/openapi/openapi.json` on every
 * run and would silently re-bake whatever that document's `servers` entry
 * says; this file is hand-written and gitignore-exempt, so it is the one
 * place the override survives regeneration.
 *
 * gate-remediation-web.md M-2: the emitted client previously defaulted to
 * `baseUrl: 'http://127.0.0.1:8080'` (the contract's dev `servers` entry)
 * with no `credentials`, so a request made from the deployed SPA would have
 * gone to the wrong origin entirely, and even pointed at the right origin it
 * would never have carried the session cookie. Both are wrong for a
 * same-origin deployment behind Caddy:
 *
 *   - `baseUrl: ''` — every request is relative to wherever the SPA itself
 *     was served from, which is exactly where Caddy proxies `/auth`,
 *     `/health`, and `/ready` too. No environment-specific origin to get
 *     wrong, no CORS.
 *   - `credentials: 'same-origin'` — the `__Host-` session cookie rides
 *     along on same-origin requests without ever being attached to a
 *     cross-origin one, matching `apps/web/src/api/pending-contracts.ts`'s
 *     hand-written client (M-2's other half) and the cookie's own `__Host-`
 *     prefix contract.
 */
export function createClientConfig(config: ClientRuntimeConfig): ClientRuntimeConfig {
  return {
    ...config,
    baseUrl: '',
    credentials: 'same-origin',
  };
}
